css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .34); position: relative; display: flex; gap: 4%; align-items: stretch; }
.loader span { position: relative; flex: 1; border-radius: 8px; box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 35%, transparent); animation: otp-box calc(var(--loader-speed) * 2.4) ease-in-out infinite; }
.loader span::after { content: ''; position: absolute; left: 30%; right: 30%; top: 38%; height: 24%; border-radius: 50%; background: var(--accent); transform: scale(0); animation: otp-dot calc(var(--loader-speed) * 2.4) cubic-bezier(.3, 1.5, .5, 1) infinite; }
.loader span:nth-of-type(2), .loader span:nth-of-type(2)::after { animation-delay: calc(var(--loader-speed) * .22); }
.loader span:nth-of-type(3), .loader span:nth-of-type(3)::after { animation-delay: calc(var(--loader-speed) * .44); }
.loader span:nth-of-type(4), .loader span:nth-of-type(4)::after { animation-delay: calc(var(--loader-speed) * .66); }
@keyframes otp-dot { 0%, 10% { transform: scale(0); } 26%, 74% { transform: scale(1); } 90%, 100% { transform: scale(0); } }
@keyframes otp-box { 0%, 10% { box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 30%, transparent); } 26%, 74% { box-shadow: inset 0 0 0 2px var(--accent-2); } 90%, 100% { box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 30%, transparent); } }
